/* da_test.c - tests for dynamic_array.c. Do not edit this file.

   `make m1` runs the tests for milestone 1, `make m2` those for milestones 1 and 2, and
   so on; `make test` runs them all. Each group tests one or more functions. When a test
   fails, the line number points at the CHECK that failed. If the program crashes, the
   last PASS or FAIL tells you where it got to: fix that first, then run it again.

   These tests check that your array is correct, not that it is fast: the naive array
   passes every one of them. `make growth` checks how much your array allocates. */

#include <stdio.h>

#include "alloc_stats.h"
#include "da_check.h"
#include "dynamic_array.h"

/* true if a holds exactly the n values in expected, in order. */
static bool holds(const DynamicArray *a, const int *expected, size_t n)
{
    if (da_count(a) != n) {
        return false;
    }
    for (size_t i = 0; i < n; i++) {
        int value = -1;
        if (!da_get(a, i, &value) || value != expected[i]) {
            return false;
        }
    }
    return true;
}

/* A new array holding values[0 .. n - 1], or NULL if any step fails. */
static DynamicArray *array_of(const int *values, size_t n)
{
    DynamicArray *a = da_new();
    for (size_t i = 0; a != NULL && i < n; i++) {
        if (!da_add(a, values[i])) {
            da_free(a);
            return NULL;
        }
    }
    return a;
}

/* The bytes this program has allocated and not freed. */
static size_t live_bytes(void)
{
    AllocStats s;
    alloc_stats_get(&s);
    return s.live_bytes;
}

static void test_new_and_count(void)
{
    check_section("da_new, da_count, da_free", "m1 da_new da_count da_free");
    DynamicArray *a = da_new();
    CHECK(a != NULL, "da_new returns an array");
    CHECK(da_count(a) == 0, "a new array is empty");
    CHECK(da_count(NULL) == 0, "da_count(NULL) is 0");
    da_free(a);
    da_free(NULL);
    CHECK(true, "da_free(NULL) does nothing");
}

static void test_add_and_get(void)
{
    check_section("da_add, da_get", "m1 da_add da_get");
    DynamicArray *a = da_new();
    bool all_added = true;
    for (int i = 0; i < 1000; i++) {
        all_added = da_add(a, i * 3) && all_added;
    }
    CHECK(all_added, "da_add returns true 1000 times in a row");
    CHECK(da_count(a) == 1000, "1000 adds give a count of 1000");
    bool all_read = true;
    for (int i = 0; i < 1000; i++) {
        int value = -1;
        all_read = da_get(a, (size_t) i, &value) && value == i * 3 && all_read;
    }
    CHECK(all_read, "da_get reads back every int in the order it was added");

    DynamicArray *big = da_new();
    bool big_added = true;
    for (int i = 0; i < 10000; i++) {
        big_added = da_add(big, i) && big_added;
    }
    int big_last = -1;
    CHECK(big_added && da_count(big) == 10000 && da_get(big, 9999, &big_last) && big_last == 9999,
          "10000 adds all succeed, and the last one reads back");
    da_free(big);

    int out = 42;
    CHECK(!da_get(a, 1000, &out) && out == 42,
          "da_get at index count returns false and leaves *out alone");
    CHECK(!da_get(a, (size_t) -1, &out) && out == 42,
          "da_get at a huge index returns false and leaves *out alone");
    CHECK(!da_get(a, 0, NULL), "da_get with a NULL out returns false");
    CHECK(!da_get(NULL, 0, &out) && out == 42, "da_get on NULL returns false");
    CHECK(!da_add(NULL, 1), "da_add to NULL returns false");

    DynamicArray *negatives = array_of((int[]){-1, 0, -2147483647 - 1}, 3);
    CHECK(holds(negatives, (int[]){-1, 0, -2147483647 - 1}, 3),
          "negative ints and INT_MIN are stored as they are");
    da_free(negatives);
    da_free(a);
}

static void test_insert(void)
{
    check_section("da_insert", "m3 da_insert");
    DynamicArray *a = array_of((int[]){10, 20, 30}, 3);
    CHECK(da_insert(a, 0, 5) && holds(a, (int[]){5, 10, 20, 30}, 4),
          "insert at 0 shifts everything up");
    CHECK(da_insert(a, 2, 15) && holds(a, (int[]){5, 10, 15, 20, 30}, 5),
          "insert in the middle shifts the rest up");
    CHECK(da_insert(a, 5, 35) && holds(a, (int[]){5, 10, 15, 20, 30, 35}, 6),
          "insert at count adds to the end");
    CHECK(!da_insert(a, 7, 99) && holds(a, (int[]){5, 10, 15, 20, 30, 35}, 6),
          "insert past count returns false and changes nothing");
    CHECK(!da_insert(NULL, 0, 1), "insert into NULL returns false");

    DynamicArray *b = da_new();
    CHECK(da_insert(b, 0, 7) && holds(b, (int[]){7}, 1), "insert at 0 of an empty array");
    bool all = true;
    for (int i = 0; i < 200; i++) {
        all = da_insert(b, 0, i) && all;
    }
    int first = -1, last = -1;
    CHECK(all && da_count(b) == 201 && da_get(b, 0, &first) && first == 199 &&
              da_get(b, 200, &last) && last == 7,
          "200 inserts at the front keep their order");
    da_free(b);
    da_free(a);
}

static void test_set(void)
{
    check_section("da_set", "m2 da_set");
    DynamicArray *a = array_of((int[]){1, 2, 3}, 3);
    CHECK(da_set(a, 1, 20) && holds(a, (int[]){1, 20, 3}, 3), "da_set replaces one int");
    CHECK(!da_set(a, 3, 9) && holds(a, (int[]){1, 20, 3}, 3),
          "da_set at index count returns false and changes nothing");
    CHECK(!da_set(NULL, 0, 9), "da_set on NULL returns false");
    da_free(a);
}

static void test_copy_to(void)
{
    check_section("da_copy_to", "m3 da_copy_to");
    DynamicArray *a = array_of((int[]){4, 5, 6}, 3);
    int dest[5] = {-1, -1, -1, -1, -1};
    CHECK(da_copy_to(a, dest, 5) && dest[0] == 4 && dest[1] == 5 && dest[2] == 6 && dest[3] == -1,
          "da_copy_to copies the data and writes nothing after it");
    int small[2] = {-1, -1};
    CHECK(!da_copy_to(a, small, 2) && small[0] == -1 && small[1] == -1,
          "da_copy_to into a destination too small returns false and writes nothing");
    CHECK(!da_copy_to(a, NULL, 5), "da_copy_to into NULL returns false");
    CHECK(!da_copy_to(NULL, dest, 5), "da_copy_to from NULL returns false");
    DynamicArray *empty = da_new();
    CHECK(da_copy_to(empty, small, 0), "an empty array copies into a length-0 destination");
    da_free(empty);
    da_free(a);
}

static void test_index_of_and_contains(void)
{
    check_section("da_index_of, da_contains", "m3 da_index_of da_contains");
    DynamicArray *a = array_of((int[]){7, 8, 9, 8}, 4);
    size_t index = 99;
    CHECK(da_index_of(a, 8, &index) && index == 1, "da_index_of finds the first occurrence");
    CHECK(da_index_of(a, 7, &index) && index == 0, "da_index_of finds index 0");
    index = 99;
    CHECK(!da_index_of(a, 5, &index) && index == 99,
          "da_index_of of a missing int returns false and leaves *index alone");
    CHECK(!da_index_of(a, 8, NULL), "da_index_of with a NULL index returns false");
    CHECK(!da_index_of(NULL, 8, &index), "da_index_of on NULL returns false");
    CHECK(da_contains(a, 9) && !da_contains(a, 10), "da_contains finds 9 and not 10");
    CHECK(!da_contains(NULL, 9), "da_contains on NULL returns false");
    da_free(a);
}

static void test_remove_at(void)
{
    check_section("da_remove_at", "m3 da_remove_at");
    DynamicArray *a = array_of((int[]){1, 2, 3, 4, 5}, 5);
    int out = -1;
    CHECK(da_remove_at(a, 1, &out) && out == 2 && holds(a, (int[]){1, 3, 4, 5}, 4),
          "remove_at in the middle returns the int and shifts the rest down");
    CHECK(da_remove_at(a, 3, &out) && out == 5 && holds(a, (int[]){1, 3, 4}, 3),
          "remove_at the last index");
    CHECK(da_remove_at(a, 0, NULL) && holds(a, (int[]){3, 4}, 2),
          "remove_at with a NULL out still removes");
    out = 42;
    CHECK(!da_remove_at(a, 2, &out) && out == 42 && holds(a, (int[]){3, 4}, 2),
          "remove_at index count returns false and changes nothing");
    CHECK(!da_remove_at(NULL, 0, &out), "remove_at on NULL returns false");
    CHECK(da_remove_at(a, 0, NULL) && da_remove_at(a, 0, NULL) && da_count(a) == 0,
          "removing everything leaves an empty array");
    CHECK(da_add(a, 6) && holds(a, (int[]){6}, 1), "an emptied array can be added to again");
    da_free(a);
}

static void test_remove(void)
{
    check_section("da_remove", "m3 da_remove");
    DynamicArray *a = array_of((int[]){1, 2, 1, 3}, 4);
    CHECK(da_remove(a, 1) && holds(a, (int[]){2, 1, 3}, 3),
          "da_remove removes only the first occurrence");
    CHECK(!da_remove(a, 9) && holds(a, (int[]){2, 1, 3}, 3),
          "da_remove of a missing int returns false and changes nothing");
    CHECK(!da_remove(NULL, 1), "da_remove on NULL returns false");
    da_free(a);
}

static void test_clear(void)
{
    check_section("da_clear", "m3 da_clear");
    DynamicArray *a = array_of((int[]){1, 2, 3}, 3);
    da_clear(a);
    CHECK(da_count(a) == 0, "da_clear empties the array");
    CHECK(da_add(a, 4) && holds(a, (int[]){4}, 1), "a cleared array can be added to again");
    da_clear(NULL);
    CHECK(true, "da_clear(NULL) does nothing");
    da_free(a);
}

static void test_reserve(void)
{
    check_section("da_reserve", "m2 da_reserve");
    DynamicArray *a = array_of((int[]){1, 2}, 2);
    CHECK(da_reserve(a, 1000) && holds(a, (int[]){1, 2}, 2),
          "da_reserve returns true and keeps the contents");
    AllocStats before, after;
    alloc_stats_get(&before);
    bool all = true;
    for (int i = 0; i < 998; i++) {
        all = da_add(a, i) && all;
    }
    alloc_stats_get(&after);
    CHECK(all && da_count(a) == 1000, "adds after da_reserve succeed");
    CHECK(after.allocs == before.allocs, "adding up to the reserved size allocates nothing");
    CHECK(da_reserve(a, 10) && da_count(a) == 1000,
          "reserving less than the count changes nothing");
    CHECK(!da_reserve(NULL, 10), "da_reserve on NULL returns false");
    da_free(a);
}

static void test_out_of_memory_new_and_add(void)
{
    check_section("running out of memory (milestone 1)", "m1 da_new da_add");
    size_t baseline = live_bytes();

    alloc_fail_after(0);
    DynamicArray *none = da_new();
    alloc_fail_never();
    CHECK(none == NULL && live_bytes() == baseline,
          "da_new returns NULL and leaks nothing when malloc fails");

    bool adds_ok = true;
    for (size_t k = 0; k < 40; k++) {
        DynamicArray *a = da_new();
        int expected[30];
        size_t n = 0;
        alloc_fail_after(k);
        for (int v = 0; v < 30; v++) {
            if (da_add(a, v)) {
                expected[n++] = v;
            }
            adds_ok = adds_ok && holds(a, expected, n);
        }
        alloc_fail_never();
        da_free(a);
    }
    CHECK(adds_ok, "a da_add that fails leaves the array unchanged, whichever malloc fails");
    CHECK(live_bytes() == baseline, "these tests leaked nothing, failed calls included");
}

static void test_out_of_memory_reserve(void)
{
    check_section("running out of memory (milestone 2)", "m2 da_reserve");
    size_t baseline = live_bytes();
    DynamicArray *a = array_of((int[]){1, 2, 3}, 3);
    alloc_fail_after(0);
    bool reserved = da_reserve(a, 1u << 20);
    alloc_fail_never();
    CHECK(!reserved && holds(a, (int[]){1, 2, 3}, 3),
          "a da_reserve that fails returns false and leaves the array unchanged");
    da_free(a);
    CHECK(live_bytes() == baseline, "this test leaked nothing, the failed da_reserve included");
}

static void test_out_of_memory_insert(void)
{
    check_section("running out of memory (milestone 3)", "m3 da_insert");
    size_t baseline = live_bytes();
    bool inserts_ok = true;
    for (size_t k = 0; k < 40; k++) {
        DynamicArray *a = da_new();
        int expected[30];
        size_t n = 0;
        alloc_fail_after(k);
        for (int v = 0; v < 30; v++) {
            if (da_insert(a, 0, v)) {
                for (size_t j = n; j > 0; j--) {
                    expected[j] = expected[j - 1];
                }
                expected[0] = v;
                n++;
            }
            inserts_ok = inserts_ok && holds(a, expected, n);
        }
        alloc_fail_never();
        da_free(a);
    }
    CHECK(inserts_ok, "a da_insert that fails leaves the array unchanged, whichever malloc fails");
    CHECK(live_bytes() == baseline, "these tests leaked nothing, failed calls included");
}

static void test_no_leaks(size_t baseline)
{
    check_section("leaks", "m1 m2 m3");
    CHECK(live_bytes() == baseline, "every array the tests freed gave back all its memory");
}

/* Removes from a full array, so make asan and make valgrind see a shift that reads one
   past the count. It checks nothing itself. */
static void remove_from_full(void)
{
    DynamicArray *a = da_new();
    for (int i = 0; a != NULL && i < 8; i++) {
        da_add(a, i);
    }
    da_remove_at(a, 0, NULL);
    da_free(a);
}

/* The milestone named by arg, "1" to "4", or 0 if arg names none. */
static int milestone_of(const char *arg)
{
    if (arg[0] >= '1' && arg[0] <= '4' && arg[1] == '\0') {
        return arg[0] - '0';
    }
    return 0;
}

int main(int argc, char **argv)
{
    int milestone = argc == 2 ? milestone_of(argv[1]) : 3;
    if (argc > 2 || milestone == 0) {
        fprintf(stderr, "usage: %s [milestone: 1, 2, 3 or 4]\n", argv[0]);
        return 2;
    }
    size_t baseline = live_bytes();
    test_new_and_count();
    test_add_and_get();
    test_out_of_memory_new_and_add();
    if (milestone >= 2) {
        test_reserve();
        test_set();
        test_out_of_memory_reserve();
    }
    if (milestone >= 3) {
        test_copy_to();
        test_index_of_and_contains();
        test_insert();
        test_remove_at();
        remove_from_full();
        test_remove();
        test_clear();
        test_out_of_memory_insert();
    }
    test_no_leaks(baseline);
    if (argc == 1) {
        return check_summary();
    }
    printf("\n%d of %d milestone %d tests passed\n", check_passed, check_passed + check_failed,
           milestone);
    return check_failed == 0 ? 0 : 1;
}
